{
  "task_summary": "Predict whether an individual's annual income exceeds $50,000 from ACS person-level attributes.",
  "ranking": [
    {
      "rank": 1,
      "feature": "SCHL",
      "rationale": "Educational attainment is a strong, semantically stable predictor of earnings across states."
    },
    {
      "rank": 2,
      "feature": "OCCP",
      "rationale": "Occupation directly reflects labor-market role and is broadly predictive of income, though job mix varies by state."
    },
    {
      "rank": 3,
      "feature": "WKHP",
      "rationale": "Usual hours worked per week is closely tied to earnings and should generalize well across regions."
    },
    {
      "rank": 4,
      "feature": "COW",
      "rationale": "Class of worker captures employment sector and work arrangement, which are meaningfully related to income."
    },
    {
      "rank": 5,
      "feature": "AGEP",
      "rationale": "Age proxies experience and career stage, making it predictive but somewhat indirect."
    },
    {
      "rank": 6,
      "feature": "MAR",
      "rationale": "Marital status correlates with income through life stage and household structure but is not a direct earnings mechanism."
    },
    {
      "rank": 7,
      "feature": "RELP",
      "rationale": "Relationship to household reference person can proxy household role and age structure, but is relatively indirect."
    },
    {
      "rank": 8,
      "feature": "SEX",
      "rationale": "Sex may be predictive due to labor-market disparities but is a demographic shortcut rather than a robust causal feature."
    },
    {
      "rank": 9,
      "feature": "RAC1P",
      "rationale": "Race can encode structural inequality and local demographics, making it brittle and ethically undesirable as a shortcut."
    },
    {
      "rank": 10,
      "feature": "POBP",
      "rationale": "Place of birth is likely to encode geography, migration patterns, and state-specific artifacts rather than stable income mechanisms."
    }
  ]
}
